    # remove pseudo deleted spans first; repeated for nested/simple spans
    prev=None
    while prev!=s:
      prev=s
      s=re.sub(r'\[DELETED:\s*.*?\]', '', s, flags=re.S)
    s=re.sub(r'\[ADDED:\s*(.*?)\]', lambda m:m.group(1), s, flags=re.S)
    # Draft pseudo-redline wrappers sometimes use markdown-like markers
    s=s.replace('{.underline}','').replace('### ','')
    s=re.sub(r'\s{2,}',' ',s)
