import zipfile,re,os
from lxml import etree
src='documents/technova-ai-vendor-agreement-draft-2-redline.docx'; out='scratch/draft2-clean-normalized.docx'
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'; ns={'w':W}; q=lambda t:'{'+W+'}'+t

def strip_inline(s):
    s=s.replace('\u00a0',' ')
    while True:
      ns0=re.sub(r'\[DELETED:\s*([^\]]*)\]', '', s, flags=re.S)
      ns0=re.sub(r'\[ADDED:\s*([^\]]*)\]', lambda m:m.group(1), ns0, flags=re.S)
      if ns0==s: break
      s=ns0
    s=s.replace('{.underline}','').replace('### ','')
    s=re.sub(r'\s{2,}',' ',s)
    return s.strip()

def raw_text(p):
    parts=[]
    for el in p.iter():
      if el.tag==q('t'): parts.append(el.text or '')
      elif el.tag==q('tab'): parts.append('\t')
      elif el.tag==q('br'): parts.append('\n')
    return ''.join(parts)

def process_marker(raw, state):
    # current text after choosing actual tracked content; handle literal multi-paragraph pseudo markup
    out=''; s=raw
    while s:
      if state=='deleted':
        if ']' in s:
          s=s.split(']',1)[1]; state=None; continue
        return '', state
      if state=='added':
        if ']' in s:
          before,s=s.split(']',1); out+=before; state=None; continue
        out+=s; return strip_inline(out), state
      # normal: find next marker
      md=s.find('[DELETED:')
      ma=s.find('[ADDED:')
      poss=[x for x in [md,ma] if x>=0]
      if not poss:
        out+=s; break
      pos=min(poss); out+=s[:pos]
      if pos==md:
        s=s[pos+len('[DELETED:'):]; state='deleted'
      else:
        s=s[pos+len('[ADDED:'):]; state='added'
    return strip_inline(out), state

with zipfile.ZipFile(src) as zin, zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as zout:
 for item in zin.infolist():
  data=zin.read(item.filename)
  if item.filename.endswith('.xml'):
   try:
    root=etree.fromstring(data)
    state=None
    for p in root.xpath('.//w:p',namespaces=ns):
      raw=raw_text(p)
      text,state=process_marker(raw,state)
      pPr=p.find(q('pPr'))
      for child in list(p):
        if child is not pPr: p.remove(child)
      if text:
        r=etree.SubElement(p,q('r')); t=etree.SubElement(r,q('t'))
        if text.startswith(' ') or text.endswith(' ') or '  ' in text: t.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
        t.text=text
    data=etree.tostring(root,xml_declaration=True,encoding='UTF-8',standalone=True)
   except Exception as e:
    print('skip',item.filename,e)
  zout.writestr(item,data)
print(out)
